DO $cases$
DECLARE item record;
BEGIN
 FOR item IN SELECT * FROM pg_temp.url_cases LOOP
 IF private.is_safe_external_url_v1(item.input) IS DISTINCT FROM item.expected THEN
 RAISE EXCEPTION 'URL case % failed', item.id;
 END IF;
 END LOOP;
 IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_proc WHERE oid = 'private.is_safe_external_url_v1(text)'::regprocedure
 AND provolatile = 'i' AND NOT prosecdef AND proconfig @> ARRAY['search_path=""']) THEN
 RAISE EXCEPTION 'Validator function contract differs'; END IF;
 IF (SELECT pg_catalog.array_agg(attname::text ORDER BY attnum) FROM pg_catalog.pg_attribute
 WHERE attrelid = 'public.public_band_profiles'::regclass AND attnum > 0 AND NOT attisdropped)
 IS DISTINCT FROM ARRAY['name','slug','description','logo_url','links'] THEN
 RAISE EXCEPTION 'Public view column contract differs'; END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_class WHERE oid = 'public.public_band_profiles'::regclass
 AND relowner = 'bandup_public_reader'::regrole
 AND reloptions @> ARRAY['security_barrier=true','security_invoker=false']) THEN
 RAISE EXCEPTION 'Public view security contract differs'; END IF;
END;
$cases$;
-- ADMINISTRATIVE PHASE: inspect existing pre-Migration-9 synthetic legacy rows.
-- Never disable the installed trigger or manufacture unsafe legacy rows after migration.
CREATE FUNCTION pg_temp.url_assert(ok boolean, label text)
RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $assert$
BEGIN
  IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'URL assertion failed: %', label; END IF;
  RAISE NOTICE 'PASS: %', label;
END;
$assert$;
CREATE FUNCTION pg_temp.url_reject(command text, expected_state text,
  expected_constraint text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $reject$
DECLARE actual_state text; actual_constraint text;
BEGIN
  BEGIN
    EXECUTE command;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS actual_state = RETURNED_SQLSTATE, actual_constraint = CONSTRAINT_NAME;
    IF actual_state = expected_state AND
       (expected_constraint IS NULL OR actual_constraint = expected_constraint) THEN
      RAISE NOTICE 'PASS: expected rejection % / %', actual_state, actual_constraint;
      RETURN;
    END IF;
    RAISE;
  END;
  RAISE EXCEPTION 'Expected rejection did not occur';
END;
$reject$;
CREATE FUNCTION pg_temp.url_actor(user_id text)
RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $actor$
BEGIN
  PERFORM pg_catalog.set_config('request.jwt.claim.sub', user_id, true);
  PERFORM pg_catalog.set_config('request.jwt.claims',
    pg_catalog.json_build_object('sub', user_id, 'role', 'authenticated')::text, true);
END;
$actor$;
CREATE FUNCTION pg_temp.url_zero(command text)
RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $zero$
DECLARE affected bigint;
BEGIN
  EXECUTE command;
  GET DIAGNOSTICS affected = ROW_COUNT;
  PERFORM pg_temp.url_assert(affected = 0, 'unauthorized update affects zero rows');
END;
$zero$;
DO $legacy_prerequisites$
DECLARE fixture_band_id uuid; public_legacy uuid; hidden_legacy uuid; admin_id uuid;
  member_id uuid; outsider_id uuid; expected_profile jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger
    WHERE tgrelid = 'public.social_links'::regclass
      AND tgname = 'social_links_zz_guard_external_url' AND tgenabled = 'O'
      AND tgtype = 23 AND NOT tgisinternal
      AND tgfoid = 'private.guard_external_link_url_v1()'::regprocedure) THEN
    RAISE EXCEPTION 'Real URL trigger is missing, disabled or structurally different';
  END IF;
  IF EXISTS (SELECT 1 FROM public.social_links
    WHERE id IN ('96000000-0000-0000-0000-000000000001',
      '96000000-0000-0000-0000-000000000002','96000000-0000-0000-0000-000000000003')) THEN
    RAISE EXCEPTION 'URL test IDs collide with existing records; never reuse them';
  END IF;
  SELECT id INTO fixture_band_id FROM public.bands
    WHERE slug = 'url-safety-20261027a-a' AND is_public IS TRUE;
  SELECT id INTO public_legacy FROM public.social_links
    WHERE social_links.band_id = fixture_band_id AND is_public IS TRUE AND url = 'javascript:alert(1)';
  SELECT id INTO hidden_legacy FROM public.social_links
    WHERE social_links.band_id = fixture_band_id AND is_public IS FALSE AND url LIKE 'https://%:%@%'
    ORDER BY id LIMIT 1;
  SELECT user_id INTO admin_id FROM public.band_members
    WHERE band_members.band_id = fixture_band_id AND role = 'admin' ORDER BY user_id LIMIT 1;
  SELECT user_id INTO member_id FROM public.band_members
    WHERE band_members.band_id = fixture_band_id AND role = 'member' ORDER BY user_id LIMIT 1;
  SELECT u.id INTO outsider_id FROM auth.users u
    WHERE NOT EXISTS (SELECT 1 FROM public.band_members m WHERE m.user_id = u.id)
    ORDER BY u.id LIMIT 1;
  IF fixture_band_id IS NULL OR public_legacy IS NULL OR hidden_legacy IS NULL
     OR admin_id IS NULL OR member_id IS NULL OR outsider_id IS NULL THEN
    RAISE EXCEPTION 'Required pre-migration URL safety synthetic fixtures missing; do not bypass guards to create them';
  END IF;
  PERFORM pg_catalog.set_config('urltest.band', fixture_band_id::text, true);
  PERFORM pg_catalog.set_config('urltest.public_legacy', public_legacy::text, true);
  PERFORM pg_catalog.set_config('urltest.hidden_legacy', hidden_legacy::text, true);
  PERFORM pg_catalog.set_config('urltest.admin', admin_id::text, true);
  PERFORM pg_catalog.set_config('urltest.member', member_id::text, true);
  PERFORM pg_catalog.set_config('urltest.outsider', outsider_id::text, true);
  SELECT pg_catalog.jsonb_build_object('name', b.name, 'slug', b.slug,
    'description', b.description, 'logo_url', b.logo_url, 'links', COALESCE((
      SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('platform', l.platform, 'url', l.url)
        ORDER BY l.created_at, l.id) FROM public.social_links l
      WHERE l.band_id = b.id AND l.is_public IS TRUE
        AND private.is_safe_external_url_v1(l.url) IS TRUE), '[]'::jsonb))
    INTO expected_profile FROM public.bands b WHERE b.id = fixture_band_id;
  PERFORM pg_catalog.set_config('urltest.expected_profile', expected_profile::text, true);
END;
$legacy_prerequisites$;

-- ANONYMOUS PHASE: full returned rows, not an HTTP-200 or LIMIT-0 smoke test.
SET LOCAL ROLE anon;
SELECT pg_temp.url_assert(CURRENT_USER = 'anon', 'anonymous role active');
SELECT pg_temp.url_assert((SELECT pg_catalog.to_jsonb(p) =
  pg_catalog.current_setting('urltest.expected_profile')::jsonb
  FROM public.public_band_profiles p WHERE slug = 'url-safety-20261027a-a'),
  'public view preserves safe URLs/keys/order and omits selected unsafe legacy rows');
SELECT pg_temp.url_assert(NOT EXISTS (SELECT 1 FROM public.public_band_profiles p,
  LATERAL pg_catalog.jsonb_array_elements(p.links) item
  WHERE p.slug = 'url-safety-20261027a-a' AND
    (item->>'url' = 'javascript:alert(1)' OR item->>'url' LIKE 'https://%:%@%')),
  'known unsafe selected legacy URLs never escape through the raw view');
SELECT pg_temp.url_assert(NOT EXISTS (SELECT 1 FROM public.public_band_profiles
  WHERE slug = 'url-safety-20261027a-b'), 'private band is absent');
SELECT pg_temp.url_assert((SELECT links = '[]'::jsonb FROM public.public_band_profiles
  WHERE slug = 'url-safety-20261027a-empty'), 'public empty band retains []');
SELECT pg_temp.url_reject('SELECT url FROM public.social_links', '42501');
SELECT pg_temp.url_reject($q$INSERT INTO public.social_links(band_id,platform,url)
  VALUES (current_setting('urltest.band')::uuid,'website','https://example.invalid/anon')$q$, '42501');
RESET ROLE;

-- AUTHENTICATED ADMIN PHASE: every operation reaches the real source-table trigger.
SET LOCAL ROLE authenticated;
SELECT pg_temp.url_actor(pg_catalog.current_setting('urltest.admin'));
SELECT pg_temp.url_assert(CURRENT_USER = 'authenticated', 'authenticated role active');
DO $unsafe_writes$
DECLARE command text;
BEGIN
  FOREACH command IN ARRAY ARRAY[
    $q$INSERT INTO public.social_links(band_id,platform,url) VALUES
      (current_setting('urltest.band')::uuid,'website','javascript:alert(1)')$q$,
    $q$INSERT INTO public.social_links(band_id,platform,url,is_public) VALUES
      (current_setting('urltest.band')::uuid,'website','https://u:p@example.invalid',true)$q$,
    $q$UPDATE public.social_links SET platform='blocked metadata'
      WHERE id=current_setting('urltest.public_legacy')::uuid$q$,
    $q$UPDATE public.social_links SET is_public=true
      WHERE id=current_setting('urltest.hidden_legacy')::uuid$q$,
    $q$UPDATE public.social_links SET url='ftp://example.invalid'
      WHERE id=current_setting('urltest.hidden_legacy')::uuid$q$,
    $q$INSERT INTO public.social_links(id,band_id,platform,url,is_public) VALUES
      (current_setting('urltest.hidden_legacy')::uuid,current_setting('urltest.band')::uuid,
       'website','javascript:alert(1)',false) ON CONFLICT(id) DO UPDATE SET url=EXCLUDED.url$q$,
    $q$INSERT INTO public.social_links(id,band_id,platform,url) VALUES
      ('96000000-0000-0000-0000-000000000001',current_setting('urltest.band')::uuid,'website','https://example.invalid/batch'),
      ('96000000-0000-0000-0000-000000000002',current_setting('urltest.band')::uuid,'website','javascript:alert(1)')$q$
  ] LOOP
    PERFORM pg_temp.url_reject(command, '23514', 'social_links_external_url_safe');
  END LOOP;
  PERFORM pg_temp.url_assert(NOT EXISTS (SELECT 1 FROM public.social_links
    WHERE id IN ('96000000-0000-0000-0000-000000000001','96000000-0000-0000-0000-000000000002')),
    'invalid multirow insert rolls back the entire statement');
END;
$unsafe_writes$;
-- Positive cases also assert persisted values; zero-row success is not enough.
UPDATE public.social_links SET is_public=false
  WHERE id=pg_catalog.current_setting('urltest.public_legacy')::uuid;
SELECT pg_temp.url_assert((SELECT NOT is_public AND url='javascript:alert(1)' FROM public.social_links
  WHERE id=pg_catalog.current_setting('urltest.public_legacy')::uuid), 'hide legacy without changing URL');
SELECT pg_temp.url_reject($q$UPDATE public.social_links SET is_public=true
  WHERE id=current_setting('urltest.public_legacy')::uuid$q$, '23514','social_links_external_url_safe');
UPDATE public.social_links SET platform='hidden metadata'
  WHERE id=pg_catalog.current_setting('urltest.hidden_legacy')::uuid;
SELECT pg_temp.url_assert((SELECT NOT is_public AND platform='hidden metadata' FROM public.social_links
  WHERE id=pg_catalog.current_setting('urltest.hidden_legacy')::uuid), 'hidden legacy metadata remains editable');
UPDATE public.social_links SET url='https://example.invalid/repaired',is_public=true
  WHERE id=pg_catalog.current_setting('urltest.hidden_legacy')::uuid;
SELECT pg_temp.url_assert((SELECT is_public AND url='https://example.invalid/repaired' FROM public.social_links
  WHERE id=pg_catalog.current_setting('urltest.hidden_legacy')::uuid), 'repair and publish legacy atomically');
INSERT INTO public.social_links(id,band_id,platform,url,is_public) VALUES
  ('96000000-0000-0000-0000-000000000003',pg_catalog.current_setting('urltest.band')::uuid,
   'website','https://example.invalid/valid-insert',false);
INSERT INTO public.social_links(id,band_id,platform,url,is_public) VALUES
  ('96000000-0000-0000-0000-000000000003',pg_catalog.current_setting('urltest.band')::uuid,
   'website','https://example.invalid/valid-upsert',true)
ON CONFLICT(id) DO UPDATE SET url=EXCLUDED.url,is_public=EXCLUDED.is_public;
SELECT pg_temp.url_assert((SELECT is_public AND url='https://example.invalid/valid-upsert'
  FROM public.social_links WHERE id='96000000-0000-0000-0000-000000000003'), 'safe insert/upsert preserves publication');
SELECT pg_temp.url_reject($q$UPDATE public.social_links SET url='https://u:p@example.invalid'
  WHERE id='96000000-0000-0000-0000-000000000003'$q$, '23514','social_links_external_url_safe');

-- MEMBER / OUTSIDER PHASES: RLS must protect even syntactically valid writes.
SELECT pg_temp.url_actor(pg_catalog.current_setting('urltest.member'));
SELECT pg_temp.url_reject($q$INSERT INTO public.social_links(band_id,platform,url)
  VALUES(current_setting('urltest.band')::uuid,'website','https://example.invalid/member')$q$, '42501');
SELECT pg_temp.url_zero($q$UPDATE public.social_links SET url='https://example.invalid/member'
  WHERE id='96000000-0000-0000-0000-000000000003'$q$);
SELECT pg_temp.url_actor(pg_catalog.current_setting('urltest.outsider'));
SELECT pg_temp.url_assert(NOT EXISTS (SELECT 1 FROM public.social_links
  WHERE band_id=pg_catalog.current_setting('urltest.band')::uuid), 'outsider cannot read band links');
SELECT pg_temp.url_zero($q$UPDATE public.social_links SET is_public=false
  WHERE id='96000000-0000-0000-0000-000000000003'$q$);
SELECT pg_temp.url_reject($q$INSERT INTO public.social_links(band_id,platform,url)
  VALUES(current_setting('urltest.band')::uuid,'website','https://example.invalid/outsider')$q$, '42501');
RESET ROLE;

-- Recompute expected JSON administratively, then recheck as anonymous after real writes.
SELECT pg_catalog.set_config('urltest.expected_links', COALESCE((SELECT pg_catalog.jsonb_agg(
  pg_catalog.jsonb_build_object('platform',platform,'url',url) ORDER BY created_at,id)
  FROM public.social_links WHERE band_id=pg_catalog.current_setting('urltest.band')::uuid
    AND is_public IS TRUE AND private.is_safe_external_url_v1(url) IS TRUE),'[]'::jsonb)::text,true);
SET LOCAL ROLE anon;
SELECT pg_temp.url_assert((SELECT links=pg_catalog.current_setting('urltest.expected_links')::jsonb
  FROM public.public_band_profiles WHERE slug='url-safety-20261027a-a'),
  'view follows repair/upsert and still filters every remaining unsafe selected legacy');
RESET ROLE;
ROLLBACK;
